R[1652]['source_statement']=R[1652]['source_statement'].replace('tongue/food-pipe or throat/lung-pipe','tongue and the source weesell-pipe of the throat or lung-pipe')
R[1664]['source_statement']='Inspect lunar separation/application and conjunction/square/opposition. A malefic configuration is said to extend illness almost to death; fortunes bring faster remedy. This is not an unconditional death assertion.'
R[1665]['source_statement']='Lunar speed and increase in light are inspected separately, including both occurring together or neither; no numerical threshold is supplied here.'
R[1668]['source_statement']='The Moon decreasing in light and motion, in square or opposition to Saturn, is assigned an incurable mortal illness unless disease vigour remits immediately after Saturn opposition. Benefic application is separately said to bring speedy cure.'
R[1680]['source_statement']='Cancer is associated with breast/phlegm/respiratory and fever complaints. Decreasing Moon near Saturn body is linked to long duration; a further clause adds ascendant-lord impediment by the eighth lord to lunar affliction for small hopes of recovery.'
R[1680]['exceptions_and_modifiers']=['Keep the proximity-duration clause separate from the further ascendant/eighth-ruler impediment clause; their compact connection is not a licensed universal Boolean formula.','Cross-page continuation PDF308–309 is one row.']
R[1684]['source_statement']='Scorpio is associated with anal, haemorrhoidal and genital complaints. A first-person passage explicitly states no retention of Urine, alongside bladder stones, dropsical swelling and sex-differentiated discharge.'
R[1684]['source_quote_exact']={'text':'no retention of Urine','pdf_page':310,'purpose':'polarity preservation; not a modern diagnostic interpretation'}
R[1684]['exceptions_and_modifiers'].append('Retain the printed no; do not change to urinary retention or infer a modern urinary subtype.')
R[1690]['exceptions_and_modifiers']=['After separation from Mars the NEXT application must be Saturn conjunction OR opposition, with decreasing light AND slow motion, for the small-hopes statement.','Small hopes is not a certain-death conclusion.','Historical cooling/bloodletting remarks are not endorsed.']
R[1692]['source_statement']='Gemini is linked to dangerous fever, high pulse, obstructions, hot/rank blood and unsettled body-wide pain. First-person remarks add arms/joints, reins/stone and sometimes spitting blood; no exhaustion claim is added.'
R[1694]['source_statement']='Leo is linked with strong fevers, weak pulses, disturbed mind and heart complaints. Usually dying about the ninth day after first falling sick is asserted only if other heavenly configurations accord.'
R[1695]['source_statement']='Virgo is linked to flux/miseriacks, weak pulse and food loathing; death within thirty days is asserted if fortunes do not assist. First-person difficulty removing illness is not proof of eventual recovery.'
R[1699]['source_statement']='Capricorn is linked to digestive, choleric, swelling, fever and slow-pulse complaints; first-person additions include jaundice, leanness and highly disturbed blood, with illness very hard to cure, not a verified recovery.'
R[1700]['prerequisites']+=['At onset Moon slow in motion AND decreasing in light.']
R[1701]['prerequisites']+=['Moon increasing in light AND swift in motion.']
D['status']='RECOVERY_CANDIDATE_SOURCE_CHECKED_BY_CONTROLLING_READER; INDEPENDENT_REVIEW_PENDING'
D['normalization_policy']='Read source_statement with source_details, prerequisites and exceptions. Detail fields preserve expanded source clauses; no modern diagnosis, proof of efficacy, case count or exact chart is inferred. Original source-reader notes are preserved only in recovery/original_draft/RULES.json.'
write('RULES.json',D)
