T=read('REFERENCE_TABLES.json');T['qualifier']='Saturn introduction requires decreasing light AND decreasing motion, not a numerical below-mean-speed substitute. Mars rows retain their own additional conditions. Historical only.';write('REFERENCE_TABLES.json',T)
U=read('UNRESOLVED.json')
