write('recovery/ROOT_REPAIR_LEDGER.json',{'basis':'all15 original JPGs read before candidate content; original draft frozen','changed_record_ids':[k for k in OLD if digest(OLD[k])!=digest(next(r for r in D['rules'] if r['id']==k))],'original_records':52,'new_records_added':0,'changes':'Expanded omitted source details; corrected polarity and overstrong/unsupported paraphrases; made normalized anchors explicit; kept visible pagination distinct; partitioned section coverage. Original drafts retained.','source_material':{'first_pdf':302,'last_pdf':316,'new_OCR':False},'clinical_or_predictive_validation':False})
